using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- DI Setup ---
var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));
var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();

// --- Define Tools ---
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Note Storage ---
var notes = new List<string>();

[Description("Searches the web for the given query and returns relevant results. Use this to research a topic.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search).
    return query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") =>
            """
            1. "Quantum Computing Advances in 2026" - Nature: Researchers achieve 1000-qubit processors with error rates below 0.1%.
            2. "IBM and Google Race to Quantum Advantage" - MIT Tech Review: Both companies demonstrate quantum advantage on practical optimization problems.
            3. "Quantum Computing Applications" - Science Daily: Drug discovery, cryptography, and climate modeling emerge as top use cases.
            """,
        var q when q.Contains("artificial intelligence") || q.Contains(" ai ") =>
            """
            1. "AI Agents Transform Software Development" - Wired: Autonomous coding agents handle 40% of routine programming tasks.
            2. "Regulation of AI Systems" - Reuters: EU AI Act enforcement begins with first compliance audits.
            3. "Multimodal AI Models" - ArXiv: New architectures combine vision, language, and reasoning in unified systems.
            """,
        _ =>
            $"""
            1. "Overview of {query}" - Wikipedia: General information about {query} covering history and current developments.
            2. "Latest Research on {query}" - Academic Journal: Recent peer-reviewed findings in the field.
            3. "{query} Industry Trends" - Bloomberg: Market analysis and future projections.
            """
    };
}

[Description("Saves an important finding or note for later use in the summary. Call this to record key facts discovered during research.")]
string SaveNote([Description("The note text to save")] string note)
{
    notes.Add(note);
    return $"Note saved. Total notes: {notes.Count}";
}

[Description("Retrieves all saved notes collected during the research session.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    return string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
}

// --- Create Agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic using the available tools,
        then provide a clear summary of your findings.

        Follow this process:
        1. Search the web for the topic using multiple relevant queries
        2. Save important findings as notes using the SaveNote tool
        3. After gathering enough information, retrieve your notes and synthesize them into a comprehensive summary

        Always save at least 3 notes before writing your summary.
        End your response with a clear, well-structured summary of the topic.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the Agent ---
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
Console.WriteLine($"🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(messages, session, runOptions);

Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine("📋 Research Summary:");
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine(response.Text);
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
